    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "IDLE / START",
      "entry": "Pallet leaves previous cycle (ZS-2008 drops) or initialization",
      "exit": "Pallet arrives at test position (ZS-2008 rising edge), cell in auto mode (X2), no ST20 fault active (M299 OFF), station idle"
    },
    {
      "name": "CLAMP",
      "entry": "Cycle start triggered (M201 SET)",
      "exit": "Clamp confirmed closed (ZS-2002A closed / X20 ON and ZS-2002B open / X21 OFF)"
    },
    {
      "name": "FILL",
      "entry": "Clamp confirmed closed (M202 SET)",
      "exit": "Pack pressure PT-2001 reaches fill complete threshold (14.50 kPa / D122) or fill timeout (8.0 s / T21) aborts"
    },
    {
      "name": "STABILISE",
      "entry": "Fill complete reached, fill valve closed (M203 SET)",
      "exit": "Stabilisation timer (T22) elapses"
    },
    {
      "name": "TEST",
      "entry": "Stabilisation timer elapses, baseline pressure recorded (M204 SET)",
      "exit": "Test window timer (10.0 s / T23) elapses"
    },
    {
      "name": "VENT",
      "entry": "Test window completes (M205 SET) or abort on fault/E-stop",
      "exit": "Vent timer elapses, pack pressure vented below 1.00 kPa, and PT-2001 signal healthy"
    },
    {
      "name": "UNCLAMP",
      "entry": "Vent conditions satisfied (M206 SET)",
      "exit": "Clamp confirmed open (ZS-2002B made / X21 ON and ZS-2002A clear / X20 OFF)"
    },
    {
      "name": "DONE",
      "entry": "Clamp confirmed open (M207 SET)",
      "exit": "Pallet leaves test position (ZS-2008 drops / X23 OFF)"
    }
  ],
  "interlocks": [
    {
      "cause": "Pallet sensor drops and returns during an active test",
      "effect": "Must not restart sequence (prevent re-triggering while busy)"
    },
    {
      "cause": "Cell not in auto mode, ST20 fault active, or station busy",
      "effect": "Inhibit ST20 cycle start"
    },
    {
      "cause": "Clamp confirmation lost while fill valve is open",
      "effect": "Fill valve closes immediately"
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault active during VENT",
      "effect": "Station holds in VENT with vent valve held open; unclamp inhibited"
    },
    {
      "cause": "Manual mode with PB-2010 (X25) pressed",
      "effect": "Vent valve XV-2004 (Y22) opens manually"
    },
    {
      "cause": "E-stop chain lost (X0 OFF) while busy",
      "effect": "Cycle aborts immediately to VENT with FAIL result"
    },
    {
      "cause": "Overpressure detected (> 20.00 kPa / D123)",
      "effect": "Fill valve closed, vent valve held open, cycle aborted with FAIL"
    },
    {
      "cause": "PT-2001 reading below -5.00 kPa (wire break)",
      "effect": "Cycle start inhibited, unclamp held"
    },
    {
      "cause": "Supply air low (PS-2009 lost while busy)",
      "effect": "Cycle aborts to VENT with FAIL result"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test fill pressure not reached within 8.0 s (T21 done)",
      "action": "Abort sequence to VENT, set FAIL result, illuminate ST20 fault beacon (HL-2011)"
    },
    {
      "name": "Over-pressure",
      "condition": "Pack pressure PT-2001 exceeds 20.00 kPa (D100 > D123)",
      "action": "Latch alarm M291, close fill valve, hold vent open, set FAIL result, illuminate ST20 fault beacon (HL-2011)"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading below -5.00 kPa (D100 < K-500)",
      "action": "Activate M292, inhibit cycle start, hold unclamp in VENT, illuminate ST20 fault beacon (HL-2011)"
    },
    {
      "name": "Supply air low",
      "condition": "Supply air pressure switch PS-2009 lost (X22 OFF) while ST20 is busy (M200 ON)",
      "action": "Latch alarm M293, abort sequence to VENT, set FAIL result, illuminate ST20 fault beacon (HL-2011)"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s",
      "parameter_sheet_says": "5.0 s (changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (T22 K50 at 100 ms)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21 uses OUT T200 K50, which is 100 ms base on FX5, running for 5.0 s instead of 0.5 s; device used is T200 instead of T24)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa regulator setpoint",
      "parameter_sheet_says": "15.00 kPa(g) (regulator PR-2012 set to 15.2 kPa)",
      "program_says": "Not directly controlled in PLC logic (mechanical regulator PR-2012)",
      "authoritative": "parameter sheet"
    }
  ]
}
